import assert from 'node:assert/strict';
import {spawn} from 'node:child_process';
import {cp,mkdtemp,readFile,rm,symlink,writeFile} from 'node:fs/promises';
import net from 'node:net';
import os from 'node:os';
import path from 'node:path';
const wait=ms=>new Promise(resolve=>setTimeout(resolve,ms));
const bind=port=>new Promise((resolve,reject)=>{const server=net.createServer();server.once('error',reject);server.listen(port,'127.0.0.1',()=>resolve(server));});
const reservation=await bind(0);const port=reservation.address().port;await new Promise(resolve=>reservation.close(resolve));
const sandbox=await mkdtemp(path.join(os.tmpdir(),'web-cancel-after-smoke-'));const harness=path.join(sandbox,'verify');let child,ready,output='';
try {
 await cp(process.cwd(),harness,{recursive:true,filter:source=>!['node_modules','out'].includes(path.basename(source))});
 await symlink(path.join(process.cwd(),'node_modules'),path.join(harness,'node_modules'),'dir');
 await writeFile(path.join(harness,'tests','external-cancel.spec.ts'),`import {test} from '@playwright/test';import {writeFile} from 'node:fs/promises';
test('external cancellation smoke',async({page,browser})=>{await page.goto(process.env.BASE_URL+'/pass.html');const session=await browser.newBrowserCDPSession();const info=await session.send('SystemInfo.getProcessInfo');let count=0;await writeFile('worker-writes','0');setInterval(()=>writeFile('worker-writes',String(++count)),30);await writeFile('ready.json',JSON.stringify({cliPid:process.ppid,workerPid:process.pid,browserPids:info.processInfo.filter(item=>item.type==='browser').map(item=>item.id)}));await new Promise(()=>{});});`);
 child=spawn(process.execPath,['--experimental-strip-types','scripts/to-receipt.ts','verify','--grep','external cancellation smoke'],{cwd:harness,detached:true,env:{...process.env,VERIFY_FIXTURES:'1',VERIFY_HARNESS_REGRESSIONS:'0',VERIFY_BROWSERS:'chromium',VERIFY_FIXTURE_PORT:String(port),BASE_URL:`http://127.0.0.1:${port}`},stdio:['ignore','pipe','pipe']});
 child.stdout.on('data',chunk=>{output+=chunk;});child.stderr.on('data',chunk=>{output+=chunk;});
 const closed=new Promise(resolve=>child.once('close',(code,signal)=>resolve({code,signal})));
 for(let attempt=0;attempt<500;attempt++){try{ready=JSON.parse(await readFile(path.join(harness,'ready.json'),'utf8'));break;}catch(error){if(error.code!=='ENOENT')throw error;}assert.equal(child.exitCode,null,output);await wait(40);}
 assert.ok(ready,output);assert.ok(ready.browserPids.length);await wait(120);assert.ok(Number(await readFile(path.join(harness,'worker-writes'),'utf8'))>0);
 child.kill('SIGTERM');const result=await Promise.race([closed,new Promise((_,reject)=>{setTimeout(()=>reject(new Error('wrapper did not complete cancellation')),10000).unref();})]);assert.deepEqual(result,{code:143,signal:null},output);
 const alive=async pid=>{try{process.kill(pid,0);const stat=await readFile(`/proc/${pid}/stat`,'utf8');return !/\) [ZX] /.test(stat);}catch(error){if(error.code==='ESRCH'||error.code==='ENOENT')return false;throw error;}};
 assert.equal(await alive(ready.cliPid),false);assert.equal(await alive(ready.workerPid),false);for(const pid of ready.browserPids)assert.equal(await alive(pid),false);
 const counter=await readFile(path.join(harness,'worker-writes'),'utf8');await wait(150);assert.equal(await readFile(path.join(harness,'worker-writes'),'utf8'),counter);const reusable=await bind(port);await new Promise(resolve=>reusable.close(resolve));
 console.log(JSON.stringify({wrapper_exit:result.code,playwright_cli_stopped:true,worker_stopped:true,browser_stopped:true,fixture_port_rebound:true,worker_writes_stable_after_close:true}));
} finally {
 if(ready){try{process.kill(ready.cliPid,'SIGINT');}catch(error){if(error.code!=='ESRCH')throw error;}}
 if(child&&child.exitCode===null&&child.signalCode===null)child.kill('SIGTERM');
 await rm(sandbox,{recursive:true,force:true});
}
